import { createHash } from "node:crypto";
import { createReadStream, existsSync, mkdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { dirname, resolve, sep } from "node:path";
import { Readable } from "node:stream";
import { blobConfig, blobExists, deletePrefix, ensureContainer, getBlobBuffer, getBlobText, putBlob, signedBlobUrl } from "./azure-blob";

/**
 * Private media storage. Keys are generated by trusted code only, never from a
 * request or model output. STORAGE_DRIVER=local keeps files under STORAGE_DIR;
 * STORAGE_DRIVER=azure keeps them in a private Azure Blob container and serves
 * them through short-lived signed URLs after the caller's access check.
 */
const KEY = /^[a-z0-9][a-z0-9/_.-]{0,200}$/;

export function storageRoot(): string {
  return resolve(process.env.STORAGE_DIR || resolve(process.cwd(), ".data", "media"));
}

export function keyPath(key: string): string {
  if (!KEY.test(key) || key.includes("..") || key.includes("//")) throw new Error("Invalid storage key");
  const root = storageRoot();
  const full = resolve(root, key);
  if (!full.startsWith(root + sep)) throw new Error("Invalid storage key");
  return full;
}

export function driver(): "local" | "azure" {
  return process.env.STORAGE_DRIVER === "azure" ? "azure" : "local";
}

function azure() {
  const cfg = blobConfig();
  if (!cfg) throw new Error("STORAGE_DRIVER=azure needs AZURE_STORAGE_ACCOUNT, AZURE_STORAGE_KEY and AZURE_STORAGE_CONTAINER");
  return cfg;
}

let containerReady: Promise<void> | null = null;

export async function putFile(key: string, source: string): Promise<{ key: string; bytes: number; sha256: string }> {
  return putBuffer(key, readFileSync(source));
}

export async function putBuffer(key: string, data: Buffer): Promise<{ key: string; bytes: number; sha256: string }> {
  keyPath(key);
  const sha256 = createHash("sha256").update(data).digest("hex");
  if (driver() === "azure") {
    const cfg = azure();
    containerReady ??= ensureContainer(cfg).catch((error) => { containerReady = null; throw error; });
    await containerReady;
    await putBlob(cfg, key, data, TYPES[key.split(".").pop() ?? ""] ?? "application/octet-stream");
    return { key, bytes: data.length, sha256 };
  }
  const target = keyPath(key);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, data);
  return { key, bytes: data.length, sha256 };
}

/** Copy a stored file (or a legacy absolute upload path) to a local working file for the worker. */
export async function fetchToFile(key: string, dest: string): Promise<string> {
  mkdirSync(dirname(dest), { recursive: true });
  if (key.startsWith("/")) {
    // Uploads made before the storage keys existed kept an absolute path under .data/uploads.
    const legacyRoot = resolve(process.cwd(), ".data", "uploads") + sep;
    if (!resolve(key).startsWith(legacyRoot) || !existsSync(key)) throw new Error("A clip in this montage is missing from storage.");
    writeFileSync(dest, readFileSync(key));
    return dest;
  }
  if (driver() === "azure") {
    const data = await getBlobBuffer(azure(), key);
    if (!data) throw new Error("A clip in this montage is missing from storage.");
    writeFileSync(dest, data);
    return dest;
  }
  const source = keyPath(key);
  if (!existsSync(source)) throw new Error("A clip in this montage is missing from storage.");
  writeFileSync(dest, readFileSync(source));
  return dest;
}

export async function hasFile(key: string): Promise<boolean> {
  try {
    keyPath(key);
    if (driver() === "azure") return blobExists(azure(), key);
    return existsSync(keyPath(key));
  } catch {
    return false;
  }
}

export async function removePrefix(prefix: string): Promise<void> {
  keyPath(prefix);
  if (driver() === "azure") {
    await deletePrefix(azure(), prefix);
    return;
  }
  rmSync(keyPath(prefix), { recursive: true, force: true });
}

const TYPES: Record<string, string> = {
  mp4: "video/mp4",
  jpg: "image/jpeg",
  png: "image/png",
  webp: "image/webp",
  mp3: "audio/mpeg",
  wav: "audio/wav",
  srt: "application/x-subrip; charset=utf-8",
  vtt: "text/vtt; charset=utf-8",
  m4a: "audio/mp4",
  zip: "application/zip",
  otio: "application/json; charset=utf-8",
  json: "application/json; charset=utf-8",
};

/**
 * Serve a stored file to a caller who already passed an access check. Local files
 * stream with HTTP Range support. Azure media redirects to a short-lived signed
 * URL; small text files (captions) are proxied so <track> works without CORS.
 */
export async function serveFile(key: string, request: Request, opts: { download?: string } = {}): Promise<Response> {
  if (driver() !== "azure") return streamFile(key, request, opts);
  try {
    keyPath(key);
  } catch {
    return new Response(null, { status: 404 });
  }
  const cfg = azure();
  const ext = key.split(".").pop() ?? "";
  if ((ext === "vtt" || ext === "srt") && !opts.download) {
    const text = await getBlobText(cfg, key);
    if (text === null) return new Response(null, { status: 404 });
    return new Response(text, { headers: { "content-type": TYPES[ext], "cache-control": "private, max-age=300", "x-content-type-options": "nosniff" } });
  }
  const url = signedBlobUrl(cfg, key, { minutes: 15, contentType: TYPES[ext], download: opts.download?.replaceAll(/[^a-zA-Z0-9._-]/g, "-") });
  return new Response(null, { status: 302, headers: { location: url, "cache-control": "no-store" } });
}

/** Stream a local stored file with HTTP Range support. */
export function streamFile(key: string, request: Request, opts: { download?: string } = {}): Response {
  let file: string;
  try {
    file = keyPath(key);
  } catch {
    return new Response(null, { status: 404 });
  }
  if (!existsSync(file)) return new Response(null, { status: 404 });
  const size = statSync(file).size;
  const ext = key.split(".").pop() ?? "";
  const headers = new Headers({
    "content-type": TYPES[ext] ?? "application/octet-stream",
    "accept-ranges": "bytes",
    "cache-control": "private, max-age=300",
    "x-content-type-options": "nosniff",
  });
  if (opts.download) headers.set("content-disposition", `attachment; filename="${opts.download.replaceAll(/[^a-zA-Z0-9._-]/g, "-")}"`);
  const range = request.headers.get("range");
  const match = range ? /^bytes=(\d*)-(\d*)$/.exec(range.trim()) : null;
  if (range && !match) return new Response(null, { status: 416, headers: { "content-range": `bytes */${size}` } });
  if (match) {
    let start = match[1] ? Number(match[1]) : NaN;
    let end = match[2] ? Number(match[2]) : NaN;
    if (Number.isNaN(start)) {
      start = Math.max(0, size - end);
      end = size - 1;
    } else if (Number.isNaN(end) || end >= size) end = size - 1;
    if (start > end || start >= size) return new Response(null, { status: 416, headers: { "content-range": `bytes */${size}` } });
    headers.set("content-range", `bytes ${start}-${end}/${size}`);
    headers.set("content-length", String(end - start + 1));
    const body = Readable.toWeb(createReadStream(file, { start, end })) as ReadableStream;
    return new Response(body, { status: 206, headers });
  }
  headers.set("content-length", String(size));
  return new Response(Readable.toWeb(createReadStream(file)) as ReadableStream, { status: 200, headers });
}
